package com.arjunren.banking.config;
import com.arjunren.banking.domain.Role; import com.arjunren.banking.entity.*; import com.arjunren.banking.repository.*; import java.util.UUID; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Profile; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component @Profile("dev") public class DevDataSeeder implements CommandLineRunner{private final UserRepository users;private final BankAccountRepository accounts;private final PasswordEncoder encoder;public DevDataSeeder(UserRepository u,BankAccountRepository a,PasswordEncoder e){users=u;accounts=a;encoder=e;}public void run(String...args){seed("admin@example.com","Development Admin","AdminPassword123!",Role.ADMIN);seed("customer@example.com","Development Customer","CustomerPassword123!",Role.CUSTOMER);}private void seed(String email,String name,String password,Role role){if(users.findByEmailIgnoreCase(email).isEmpty()){var u=users.save(new AppUser(email,encoder.encode(password),name,role));accounts.save(new BankAccount("AC"+UUID.randomUUID().toString().replace("-","").substring(0,18).toUpperCase(),u));}}}
